let trial=null,selected='wang',running=false,paused=false,scene=null,sound=true,sideways=false,hold={},keysHeld=new Set(),pointerHeld=new Map(),trialControls=null,captionUntil=0,feedbackUntil=0,punchWait=0,audioContext;
