function recalcHold(){hold={};for(const k of keysHeld)hold[KEY[k]]=true;for(const a of pointerHeld.values())hold[a]=true;for(const b of $$('[data-hold]'))b.classList.toggle('held',!!hold[b.dataset.hold]);}
function clearHold(){keysHeld.clear();trialControls?.clear();pointerHeld.clear();hold={};punchWait=0;$('#stick-knob').style.transform='';for(const b of $$('.held'))b.classList.remove('held');}
function soundUnlock(){if(!sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume().catch(()=>{});voices.connectAudio(audioContext);voices.prime('assets/audio-unlock-silence-v37.wav');}catch{}if(running&&!paused){$('#music').volume=.16;$('#music').play().catch(()=>{});}}
function sfx(type){if(!sound||!audioContext||audioContext.state!=='running')return;const o=audioContext.createOscillator(),g=audioContext.createGain(),now=audioContext.currentTime;const freq=type==='hit'?130:type==='jump'?480:650;o.type=type==='hit'?'triangle':'sine';o.frequency.setValueAtTime(freq,now);o.frequency.exponentialRampToValueAtTime(freq*.45,now+.14);g.gain.setValueAtTime(.035,now);g.gain.exponentialRampToValueAtTime(.001,now+.14);o.connect(g);g.connect(audioContext.destination);o.onended=()=>{o.disconnect();g.disconnect()};o.start();o.stop(now+.15);}
