$('#sound').onclick=()=>{sound=!sound;$('#sound').setAttribute('aria-pressed',String(sound));$('#sound').textContent=sound?'♪ 聲音':'♪ 靜音';voices.setVolume(sound?1:0);if(!sound){$('#music').pause();voices.stopAll()}else soundUnlock()};
function resize(){clearHold();const w=window.innerWidth,h=window.innerHeight;document.body.dataset.sideways=String(sideways&&w<h);const rotated=sideways&&w<h;app.style.width=rotated?h+'px':'';app.style.height=rotated?w+'px':'';document.body.dataset.portrait=String(!rotated&&w<h);document.body.dataset.compact=String((rotated?w:h)<520&&(rotated?h:w)>550);requestAnimationFrame(()=>{const s=$('#stage');game.scale.resize(s.clientWidth,s.clientHeight);});}
