window.addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);
window.addEventListener('blur',()=>{clearHold();if(running&&!paused)showPause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearHold();if(running&&!paused)showPause()}});
window.addEventListener('keydown',e=>{if(e.target?.closest?.('input,textarea,select,[contenteditable]'))return;if(e.code==='Escape'&&running){e.preventDefault();if(!e.repeat)paused?resume():showPause();return;}const a=KEY[e.code];if(!a||!running||paused)return;e.preventDefault();if(e.repeat||keysHeld.has(e.code))return;const alreadyHeld=!!hold[a];keysHeld.add(e.code);recalcHold();if(!['up','down','left','right','guard'].includes(a)&&!(a==='punch'&&alreadyHeld))command(a);});
