function showShout(e,time){const helper=e.type==='assistStart',actor=helper?e.helper:trial.player.type,name=e.name??CAST[actor]?.moves.find(m=>m.kind===e.kind)?.name??'';const slot=scene.shouts[helper?1:0];slot.spec={name,kind:e.kind,actor,helper};slot.started=time;$('#caption').textContent=(helper?'助拳！':'')+name;captionUntil=time+1650;}
